    "title": "AI调度系统接管望远镜开启自主观星",
    "link": "https://36kr.com/newsflashes/3923005684379008?f=rss",
    "pub_date": "2026-08-03 07:49:39",
    "author": "",
    "description": "据物理学家组织网8月1日报道，美国西北大学、芝加哥大学与费米实验室科学家，研发出一款人工智能（AI）调度系统，可接管望远镜并为望远镜规划“凝视方向”。团队表示，这是迈向“自主天文台”的重要标志。目前，该系统的决策能力已与人类调度员相当。这一AI系统已接管位于智利的维克托·M·布兰科4米望远镜，指挥5.7亿像素的“暗能量相机”展开观测。（科技日报）",
