    "description": "7月的科技股踩了一脚“急刹车”，此前高歌猛进的势头突然转向，那些靠极致持仓在顺风局中大放异彩的主动权益基金在此轮市场调整中纷纷大幅回撤，超过3500只基金月内收益告负，超过70只产品单月跌幅逾40%。有基金分析人士指出，公募基金“押宝式”的持仓看似回报丰厚，实则充满荆棘，行业应当建立起逆向销售的定力，坚决杜绝在单一赛道处于历史估值高位、交易极度拥挤时进行推波助澜式的宣传。（证券时报）",
