    "content": "中新网8月3日电 据以色列媒体2日报道，以色列官员是通过美国总统特朗普在“真相社交”上发表的帖文得知，特朗普已决定取消原定对伊朗的袭击计划。以媒还称，美国中央司令部事先也未被告知此事。"
