    "content": "遭逆转，利物浦友谊赛不敌利兹联 北京时间8月3日凌晨，足球友谊赛，利物浦在芝加哥对阵利兹联。 第7分钟，利物浦获得角球机会，钱伯斯门前推射得分。第40分钟，弗林蓬助攻维尔茨扩大比分。 然而来到下半场，利物浦连丢四球，阿伦森、勒温、朗斯塔夫接连破门，其中勒温梅开二度，最终利物浦以2比4遭逆转落败。 这样的比赛表现，无疑难以让利物浦球迷满意。而当下在转会市场上，利物浦追逐巴尔科拉的消息预计也很难快速落地。 据转会专家罗马诺透露，虽然利物浦希望引进这位法国边锋，但巴黎圣日耳曼方面开出的转会条件不菲，双方还需要更长时间的谈…"
