    "content": "你们的AI技术能不能降低能耗、能不能提升生产效率、能不能创造实实在在的经济效益？ 2026世界人工智能大会暨人工智能全球治理高级别会议（WAIC）开幕式后举行的闭门会上，李金金在完成工业AI落地实践现场汇报后，联合国秘书长古特雷斯向她抛出了上述三个问题。 李金金是上海交通大学教授、人工智能与微结构实验室（AIMS-Lab）主任、金珵科技创始人。依托十余年在AI for Science领域的专业技术经验及自主研发的AI创新性算法，她率领团队创造了一系列中国智能制造与高端装备研制的“首次”，包括：首次将时间维度AI算法…"
