    "content": "7月31日，中国外交部就菲律宾在中国领土黄岩岛划设所谓“领海基线”发布声明。8月1日，中国人民解放军南部战区在黄岩岛领海、领空和周边海空域组织海空联合演训。相关举措与行动是针对当前菲方在南海侵权挑衅行径的严正警告，展示了我维护黄岩岛主权和海洋权益的坚定决心。 黄岩岛是中国固有领土。从元代天文学家郭守敬主持“四海测验”的星盘刻度，到明代《郑和航海图》上的“石塘”印记；从1947年《南海诸岛位置图》中的“民主礁”，到新中国地名委员会1983年定名的“黄岩岛”——清晰无比的历史链条，早已将黄岩岛的主权深嵌于中国版图之中。…"
