    "description": "新华社德黑兰8月2日电（记者陈霄 沙达提）伊朗外交部发言人巴加埃在伊朗伊斯兰共和国广播电视台2日播出的节目中表示，伊朗正与阿曼讨论在霍尔木兹海峡划定一条新航线。 巴加埃说，伊朗和阿曼正致力于在分道航行制框架下，为海峡划定一条新航线，以确保双方主权权利以及伊朗的国家利益与安全。 巴加埃称，即使伊阿双方就新航线达成谅解，并不意味着霍尔木兹海峡开放或关闭；伊阿相关对话属双边事务，与任何第三方无关。他表示，如果美国寻求采取“冒险行动”，伊方将根…",
    "content": "新华社德黑兰8月2日电（记者陈霄 沙达提）伊朗外交部发言人巴加埃在伊朗伊斯兰共和国广播电视台2日播出的节目中表示，伊朗正与阿曼讨论在霍尔木兹海峡划定一条新航线。 巴加埃说，伊朗和阿曼正致力于在分道航行制框架下，为海峡划定一条新航线，以确保双方主权权利以及伊朗的国家利益与安全。 巴加埃称，即使伊阿双方就新航线达成谅解，并不意味着霍尔木兹海峡开放或关闭；伊阿相关对话属双边事务，与任何第三方无关。他表示，如果美国寻求采取“冒险行动”，伊方将根据国家利益作出相应回应。 巴加埃还说，过去24小时内，英国、保加利亚和乌克兰方面…"
