    "content": "新华社加沙8月2日电（记者赵伟宏 黄泽民）巴勒斯坦加沙地带民防部门发言人马哈茂德·巴萨勒2日在一份视频声明中表示，以军无人机当天袭击加沙地带多地，造成至少18人死亡，其中包括2名妇女和4名儿童。 巴萨勒说，以军空袭目标包括居民公寓、安置流离失所者帐篷、民用车辆以及居民集会场所。 巴萨勒说，最近一次袭击发生在当天傍晚，一架以色列无人机向加沙城一辆民用车辆发射两枚导弹，造成4人死亡；以军还在加沙城西部空袭一处帐篷，造成两人死亡，其中包括一名13岁儿童，另有8人受伤。当天下午早些时候，以军空袭加沙地带中部城市代尔拜拉赫一…"
