    "author": "周永穗",
    "description": "8月2日，巴西总统卢拉在圣保罗举行的巴西劳工党全国代表大会上发表讲话。新华社发（保罗·洛佩斯摄） 新华社里约热内卢8月2日电（记者周永穗）巴西劳工党2日正式确认现总统卢拉为该党总统候选人。卢拉将再次参加大选，角逐其第四个总统任期。 8月2日，巴西副总统阿尔克明在圣保罗举行的巴西劳工党全国代表大会上发表讲话。新华社发（保罗·洛佩斯摄） 当天，巴西劳工党全国代表大会在圣保罗举行，会议正式批准卢拉与现任副总统热拉尔多·阿尔克明（社会党）再次组…",
    "content": "8月2日，巴西总统卢拉在圣保罗举行的巴西劳工党全国代表大会上发表讲话。 新华社发（保罗·洛佩斯摄） 新华社里约热内卢8月2日电（记者周永穗）巴西劳工党2日正式确认现总统卢拉为该党总统候选人。卢拉将再次参加大选，角逐其第四个总统任期。 8月2日，巴西副总统阿尔克明在圣保罗举行的巴西劳工党全国代表大会上发表讲话。 新华社发（保罗·洛佩斯摄） 当天，巴西劳工党全国代表大会在圣保罗举行，会议正式批准卢拉与现任副总统热拉尔多·阿尔克明（社会党）再次组成竞选搭档。劳工党主席埃迪尼奥·席尔瓦在会上宣布，该党已在高等选举法院完成相…"
