    "content": "新华社北京8月2日电 题：战高温斗酷暑保民生，他们奋力前行 新华社记者魏一骏、王松涛、贾云鹏 正值“三伏”，暑气蒸腾。从车站机场到城市社区，众多平凡的劳动者不畏高温“烤”验，以坚守为责，默默守护城市正常运转、保障百姓安稳生活，成为盛夏时节最动人的风景线。 顶热浪保通途 临近中午，户外气温直逼40摄氏度，杭州东站迎来一天中的高峰时段。“请各位旅客注意脚下安全，在站台安全白线内行走，看管好自己的小孩，保管好随身物品。”“先下后上，不要拥挤。”……随着G7507次列车挟着热浪进站，杭州东站客运员李雪莉拿着扩音器，全神贯注…"
