    "content": "新华社成都8月2日电（记者李杰、肖玥）记者2日21时从中国铁路成都局集团有限公司获悉，8月2日至8月4日，四川省境内盆地东北部、重庆市境内大部、贵州省境内大部有强降雨过程，为确保安全，中国铁路成都局集团有限公司决定对8月3日铁路成都车站31趟列车采取临时停运措施。 铁路成都车站相关负责人介绍，此轮强降雨涉及西成高铁、宝成铁路、兰渝铁路、新成昆铁路、达成铁路、襄渝铁路及渝贵铁路等线路，临时停运影响到成都开往北京、上海、广州、深圳、沈阳、西宁、兰州、乌鲁木齐、喀什、昆明等方向的部分列车，包括成都始发车次和经停成都车次。…"
