    "author": "黄智琪,丁增尼达,晋美多吉",
    "description": "西藏山南市乃东区扎西曲登社区，素有 “藏戏第一村” 之称。悠扬的藏戏唱腔萦绕四周，古老非遗不再只留存于舞台。 依托藏戏文化，来自五湖四海的游客越来越多地了解这里。 一曲百年藏戏，串联起传承与生计，在雅砻河谷间，看见传统文化扎根乡土、滋养村民新生活的生动图景。 记者：黄智琪、丁增尼达 摄制：戴梦楠 新华社音视频部制作",
