    "description": "新华社北京8月2日电（记者王优玲）记者2日从住房城乡建设部获悉，住房城乡建设部城市建设司近日就防范燃气安全事故，专门约谈了有关省市部门负责人。 约谈指出，燃气安全事关人民群众切身利益，事故发生暴露出有关省市燃气安全工作存在明显薄弱环节。有关省市要深刻汲取事故教训，举一反三，采取针对性工作措施，提升本地区燃气安全管理水平。 约谈要求，有关省市要全面加强城镇燃气安全专项整治，抓紧推动落实瓶装液化石油气配送入户、随瓶安检等制度，加快消除用户端…",
    "content": "新华社北京8月2日电（记者王优玲）记者2日从住房城乡建设部获悉，住房城乡建设部城市建设司近日就防范燃气安全事故，专门约谈了有关省市部门负责人。 约谈指出，燃气安全事关人民群众切身利益，事故发生暴露出有关省市燃气安全工作存在明显薄弱环节。有关省市要深刻汲取事故教训，举一反三，采取针对性工作措施，提升本地区燃气安全管理水平。 约谈要求，有关省市要全面加强城镇燃气安全专项整治，抓紧推动落实瓶装液化石油气配送入户、随瓶安检等制度，加快消除用户端瓶管灶阀等安全隐患。要继续发挥好城镇燃气安全专项整治工作专班作用，深入推进燃气安…"
