    "author": "惠晓霜",
    "description": "新华社北京8月2日电 日本熊本县2日通报，一名地震后栖身汽车中的灾民死亡，死因疑似为中暑。熊本县首府熊本市当天出现创纪录的高温，预计3日气温将继续升高。 这是7月30日在日本熊本县拍摄的受损房屋。新华社记者贾浩成摄 根据通报，死者为一名70多岁女性，地震发生后在汽车内避难，7月30日出现中暑症状，被送医院后不治身亡。当时，汽车已经没有汽油，空调处于关闭状态。 根据熊本县灾害对策总部发布的数据，截至1日，近百人在震后因中暑送医，其中8人情…",
    "content": "新华社北京8月2日电 日本熊本县2日通报，一名地震后栖身汽车中的灾民死亡，死因疑似为中暑。熊本县首府熊本市当天出现创纪录的高温，预计3日气温将继续升高。 这是7月30日在日本熊本县拍摄的受损房屋。新华社记者贾浩成摄 根据通报，死者为一名70多岁女性，地震发生后在汽车内避难，7月30日出现中暑症状，被送医院后不治身亡。当时，汽车已经没有汽油，空调处于关闭状态。 根据熊本县灾害对策总部发布的数据，截至1日，近百人在震后因中暑送医，其中8人情况严重。中暑者中，六成为65岁以上的老人。 7月30日，在日本熊本县一处避难所，…"
