    "description": "新华社德黑兰8月2日电（记者陈霄 沙达提）据伊朗迈赫尔通讯社2日报道，伊朗代理国防部长伊本·礼萨当天表示，敌方近期有关言论虽是在心理战和认知战背景下提出的，但伊朗认为，任何威胁都是“真实且值得重视的”，并将据此提升战备水平、增强威慑能力和提高自身实力。 伊本·礼萨未说明上述表态是针对敌方哪些言论。 美国总统特朗普7月31日对媒体称，他计划恢复猛烈军事打击，以迫使伊朗回到谈判桌上。但他8月1日在社交媒体发文称，伊朗以及其他中东国家刚刚向美…",
    "content": "新华社德黑兰8月2日电（记者陈霄 沙达提）据伊朗迈赫尔通讯社2日报道，伊朗代理国防部长伊本·礼萨当天表示，敌方近期有关言论虽是在心理战和认知战背景下提出的，但伊朗认为，任何威胁都是“真实且值得重视的”，并将据此提升战备水平、增强威慑能力和提高自身实力。 伊本·礼萨未说明上述表态是针对敌方哪些言论。 美国总统特朗普7月31日对媒体称，他计划恢复猛烈军事打击，以迫使伊朗回到谈判桌上。但他8月1日在社交媒体发文称，伊朗以及其他中东国家刚刚向美方提出请求，希望暂缓打击伊朗，他因此“同意取消军事行动”。对此，伊朗迈赫尔通讯社…"
