    "content": "新华社哈尔滨8月2日电 题：哈尔滨从高校科研成果中寻找产业化潜力“种子” 新华社记者沈易瑾 走进哈尔滨新区工大卫星智造基地，洁净厂房内，卫星总装、测试、环境试验等环节有序衔接，一颗颗卫星在这里完成升空前的“体检”。 这是哈尔滨工大卫星技术有限公司的日常一幕。这家成立于2020年的高科技企业，短短数年间已完成14次发射任务，将37颗卫星送入太空，涵盖通信、导航、遥感、深空探测等领域。目前，基地具备年产180颗500公斤量级卫星的能力。 工大卫星的成长，并非“单打独斗”，而是源自哈尔滨工业大学数十年的航天科研积累。哈尔…"
