    "description": "新华社重庆8月2日电（记者 黄伟）记者近日从重庆阴条岭国家级自然保护区管理事务中心获悉，中心联合重庆师范大学生命科学学院唐安军教授团队在重庆阴条岭国家级自然保护区报春花繁育基地（种质资源圃），用种子培育并规模化栽培的川东灯台报春已喜结硕果，这标志着极度濒危植物川东灯台报春迁地保护已取得了成功。 这是7月20日在重庆阴条岭国家级自然保护区报春花繁育基地拍摄的已经结果的川东灯台报春。新华社发（唐安军 摄） 川东灯台报春花色艳丽，为中国特有植…",
    "content": "新华社重庆8月2日电（记者 黄伟）记者近日从重庆阴条岭国家级自然保护区管理事务中心获悉，中心联合重庆师范大学生命科学学院唐安军教授团队在重庆阴条岭国家级自然保护区报春花繁育基地（种质资源圃），用种子培育并规模化栽培的川东灯台报春已喜结硕果，这标志着极度濒危植物川东灯台报春迁地保护已取得了成功。 这是7月20日在重庆阴条岭国家级自然保护区报春花繁育基地拍摄的已经结果的川东灯台报春。新华社发（唐安军 摄） 川东灯台报春花色艳丽，为中国特有植物，具有较高的观赏价值。目前仅在野外发现5个极小种群，植株数量很少。 这是7月2…"
