    "author": "邹多为,熊家林,任丽颖",
    "description": "新华社石家庄8月2日电 记者手记：丝网之乡的智造交响 新华社记者邹多为、熊家林、任丽颖 广袤神州、县域藏珍。如果不是来到“中国丝网之乡”——河北安平，记者很难想象，跨越时空隧道的织机声，怎样奏出丝网产业的智造交响。 不论筛面用的细罗、净水过滤网、公路安全护栏、露营烧烤用网，还是半导体、航空航天等领域的配套配件，看似平平无奇的丝网，却在生产生活中扮演着极其重要的角色。 “丝网是安平的立县产业，它从明代的马尾编织加工起步，历经500余年发展…",
    "content": "新华社石家庄8月2日电 记者手记：丝网之乡的智造交响 新华社记者邹多为、熊家林、任丽颖 广袤神州、县域藏珍。如果不是来到“中国丝网之乡”——河北安平，记者很难想象，跨越时空隧道的织机声，怎样奏出丝网产业的智造交响。 不论筛面用的细罗、净水过滤网、公路安全护栏、露营烧烤用网，还是半导体、航空航天等领域的配套配件，看似平平无奇的丝网，却在生产生活中扮演着极其重要的角色。 “丝网是安平的立县产业，它从明代的马尾编织加工起步，历经500余年发展，已实现从传统手工业向现代产业集群的蝶变升级。”炎炎夏日，在中国·安平国际丝网展…"
