    "pub_date": "2026-08-02 18:46:39",
    "author": "李嘉聪",
    "description": "新华社雅加达8月2日电（记者李嘉聪）印度尼西亚国家搜救局2日说，一艘船当天在东爪哇省马都拉岛以北的爪哇海海域起火，造成5人死亡、41人失踪，另有225人获救。 据介绍，涉事船只名为“穆蒂亚拉·桑托萨2”号，事发时位于泗水至望加锡航线上。船上共有271人，包括232名乘客和39名船员。当时，这艘船距海岸约19海里，船体几乎被大火吞没，部分乘客在驾驶台和船头等待救援。 印尼国家搜救局说，事发海域附近多艘船只参与救援。联合搜救队还增派船只和人…",
    "content": "新华社雅加达8月2日电（记者李嘉聪）印度尼西亚国家搜救局2日说，一艘船当天在东爪哇省马都拉岛以北的爪哇海海域起火，造成5人死亡、41人失踪，另有225人获救。 据介绍，涉事船只名为“穆蒂亚拉·桑托萨2”号，事发时位于泗水至望加锡航线上。船上共有271人，包括232名乘客和39名船员。当时，这艘船距海岸约19海里，船体几乎被大火吞没，部分乘客在驾驶台和船头等待救援。 印尼国家搜救局说，事发海域附近多艘船只参与救援。联合搜救队还增派船只和人员，继续开展人员转移和失踪人员搜寻工作。目前，搜救行动仍在进行中，起火原因尚不清…"
