    "author": "黄韬铭",
    "description": "新华社北京8月2日电（记者黄韬铭）据气象部门预报，8月2日至4日，贵州自西北向东南将先后出现大到暴雨，局地大暴雨。记者从应急管理部获悉，国家防总、应急管理部2日针对贵州启动防汛四级应急响应。 据悉，国家防总办公室、应急管理部当日组织多部门联合会商，研判近期强降雨发展形势，研究部署重点地区防汛工作。 会商指出，近期降水主要在西南、西北地区东部、东北、华南等地，雨带稳定少动，重叠度高；松花江干流肇源、通河至佳木斯江段依然超警，吉林、黑龙江等…",
    "content": "新华社北京8月2日电（记者黄韬铭）据气象部门预报，8月2日至4日，贵州自西北向东南将先后出现大到暴雨，局地大暴雨。记者从应急管理部获悉，国家防总、应急管理部2日针对贵州启动防汛四级应急响应。 据悉，国家防总办公室、应急管理部当日组织多部门联合会商，研判近期强降雨发展形势，研究部署重点地区防汛工作。 会商指出，近期降水主要在西南、西北地区东部、东北、华南等地，雨带稳定少动，重叠度高；松花江干流肇源、通河至佳木斯江段依然超警，吉林、黑龙江等省份一些水库超汛限水位运行，防汛形势仍然严峻。 会商强调，要盯紧盯牢重点领域，对…"
