    "content": "（本文首发于南方人物周刊） 南方人物周刊记者 徐琳玲 责任编辑：李屾淼 《给阿嬷的情书》剧照 相关报道详见《 番客婶：下南洋潮中的留守妇女 》 2026年，一部小成本制作的潮汕方言电影《给阿嬷的情书》，让下南洋、番客婶和侨批这些地域性极强的历史人类学话题进入了大众的视野。 曾有精通世故的老前辈言：“娶妻当娶潮汕女。”在东南沿海，潮汕、闽南地区的女性素有贤惠、勤劳的传统美名。有位来自闽南农村的女作家回忆说：在她童年，村里就没有女人是在早上5点以后起床的，她们一早起来打扫、喂猪、烧早饭。至于男人们，“他们到底在干啥？”…"
