    "description": "南昌八一起义纪念馆举行灯光秀庆祝建军节，江西省。8月1日是中国人民解放军建军99周年纪念日，该节日旨在纪念1927年8月1日南昌起义事件爆发，标志着中国共产党独立创建人民军队、领导革命战争和武装夺取政权的开始。中国国防部数据显示中国人民解放军现役总兵力约200万人，是世界上规模最大的武装力量，2026年中国国防预算为1.94万亿元，同比增长6.9%。摄影师：Liu Zhankun",
