    "content": "新华社首尔8月2日电（记者姬新龙）据韩国气象厅消息，韩国多地8月2日遭遇40摄氏度以上高温天气，庆尚南道梁山日间气温连续五天超过40摄氏度，2日更升至42.5摄氏度，刷新韩国最高气温纪录。 8月2日，一名儿童和宠物狗在韩国首尔市的汉江游泳池戏水。新华社发（全休相摄） 据韩联社报道，自1973年以来，韩国日间气温连续三天以上达到40摄氏度的情况仅出现过三次。庆尚南道地处韩国南部，该道多地2日创下有气象观测记录以来本地日间气温最高纪录。釜山2日气温也超过40摄氏度。 综合韩国媒体报道，随着高温天气出现，中暑患者数量持续…"
