    "author": "国际空间站",
    "description": "美国宇航员 Jessica Meir 正在使用VR头戴设备测试视力，国际空间站。这款智能检测设备由美国内华达大学团队研发，内置多款应用程序，能够帮助宇航员在太空环境下全方位检测视觉能力，记录视力、瞳孔对光反射、色彩敏感度、对比敏感度、视野畸变等关键指标。宇航员长期生活在太空失重环境中会出现颅内压上升现象，导致眼球和视神经因受压而出现损伤。摄影师：NASA",
