    "content": "2026年肯尼亚国际太阳能展（Solar Africa）期间，一名展商在一台机器人旁浏览手机，内罗毕。7月29日，第11届肯尼亚国际太阳能展在内罗毕举行，这是非洲规模最大的可再生能源展会之一，本届展期从7月29日持续至31日，共吸引来自全球27个国家和地区的超过250家展商参展，聚焦光伏技术、储能、电力基础设施等领域的最新成果。肯尼亚政府报告显示，截至2025年底该国发电总装机容量为3868.6兆瓦，地热、水力、风能和太阳能在内的可再生能源占比超过80%，其中太阳能发电占比约为14%。摄影师：Daniel Irun…"
