    "description": "AI飞速发展，很多家长焦虑孩子未来如何不被人工智能取代。香港城市大学协理副校长、未来学习研究院院长张泽松教授，在少年科技中国行的活动现场分享了4点建议： 1、夯实基础能力； 2、重视团队协作； 3、提高孩子辨别真伪的能力； 4、专注深耕自身强项。 统筹：牟彦秋、梁甜甜、李 旭 策划：李 坤、杨欢欢 拍摄：李璐莎 制作：孟林燕（实习生） 新华网社交媒体传播中心新华网体育产业中心联合出品",
