    "description": "新华社哈尔滨8月2日电 题：哈尔滨聚力打造国家先进制造业集群 新华社记者刘赫垚、徐凯鑫 盛夏时节，哈尔滨先进制造业企业生产线一派繁忙。作为老工业基地，哈尔滨着力推动航空集群、绥哈大齐生物制造集群两大国家先进制造业集群建设，使其加速迈向规模化、高端化、智能化、绿色化发展轨道。 哈尔滨平房区是哈尔滨航空产业重要承载区，传承着哈尔滨老工业基地历史根脉。记者从哈尔滨市平房区工业信息科技局获悉，平房区已形成以航空工业哈飞、中国航发东安、中铝东轻为…",
