    "content": "新华社耶路撒冷8月2日电（记者陈君清 王卓伦）以色列国防军8月2日发表声明称，以军近日在加沙地带中部和南部实施空袭，打死两名巴勒斯坦伊斯兰抵抗运动（哈马斯）武装人员。 声明说，以军8月1日在加沙地带南部的空袭中打死哈马斯“努赫巴”部队的一名指挥官。声明称此人曾参与2023年10月7日针对以色列的袭击。7月31日，以军还在加沙地带中部打死哈马斯“马加齐营”的一名指挥官。 自2025年10月加沙停火第一阶段协议生效以来，以军仍不时对加沙地带发动空袭。 哈马斯今年7月31日发表声明说，该组织同意将移交重型武器相关议题纳入…"
