    "title": "“十五五”开局之年中国产业发展观察",
    "link": "http://www.news.cn/20260802/cdebdb0bc8c243298bfc886dc5ed6d5a/c.html",
    "pub_date": "2026-08-02 16:27:16",
    "author": "",
    "description": "开栏的话： 建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略任务。今年全国两会期间，习近平总书记在参加江苏代表团审议时强调，在优化提升传统产业、培育壮大新兴产业、超前布局未来产业上开创新局面。 “十五五”开局之年，现代化产业体系建设进展如何？各地推进产业转型升级有哪些亮点？新一轮科技革命和产业变革加速突破，如何拥抱产业发展新机遇？近期，新华社记者组成多路小分队，奔赴十余省份采访调研，触摸产业脉动，感知经济活力。即日起…",
    "content": "开栏的话： 建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略任务。今年全国两会期间，习近平总书记在参加江苏代表团审议时强调，在优化提升传统产业、培育壮大新兴产业、超前布局未来产业上开创新局面。 “十五五”开局之年，现代化产业体系建设进展如何？各地推进产业转型升级有哪些亮点？新一轮科技革命和产业变革加速突破，如何拥抱产业发展新机遇？近期，新华社记者组成多路小分队，奔赴十余省份采访调研，触摸产业脉动，感知经济活力。即日起，新华社推出“产业发展开新局”系列报道，展现各地各部门贯彻落实党中央、国务院决策…"
