    "content": "新华社香港8月2日电 香港特区政府财政司司长陈茂波2日发表网志表示，在中央相关部委的坚实支持下，各方期待已久的离岸人民币国债期货3日将在香港上市。这是香港离岸人民币业务枢纽发展的新里程，不仅丰富香港市场的人民币风险管理工具，更标志着国债在离岸市场的深化发展和人民币国际化的有序推进。 本次首只上市的离岸人民币国债期货属5年期产品，是当前唯一一只离岸市场上的同类产品，让国际投资者可沿用在港的交易账户、习惯和流程，在离岸市场完成相关合约的交易和结算。 陈茂波表示，债券通在2017年启动，让境外投资者可通过“北向通”参与内…"
