    "content": "新华社北京8月2日电（记者魏弘毅、樊曦）记者从水利部获悉，水利部2日对重庆市启动洪水防御Ⅳ级应急响应，并派出工作组赴防御一线协助指导。 据预报，8月2日至4日，重庆有中到大雨，其中重庆中部和东南部将有暴雨，局部将有大暴雨；长江上游干流及支流乌江、嘉陵江等主要河流将出现明显涨水过程，其中长江支流打鱼溪、碧溪河，乌江支流九曲河、甘龙河等中小河流可能发生超警洪水。 为应对可能出现的汛情，水利部督促指导地方水利部门密切关注雨水情变化，强化应急值守和会商研判，加强监测预报预警，科学调度水工程，做好江河防汛、水库安全度汛、中小…"
