    "content": "新华社北京8月2日电 美国首都华盛顿地标建筑林肯纪念堂倒影池改造引发的风波持续发酵。美国总统特朗普8月1日在社交媒体上“炮轰”自己亲自任命的一名联邦检察官，表示“百分百反对”后者的调查结论，即倒影池底部涂层大量脱落是因为施工问题而非蓄意破坏。 6月19日，在美国首都华盛顿，人们在林肯纪念堂前的倒影池旁休闲。新华社记者李睿摄 林肯纪念堂前有一片面积约3.2万平方米的浅水池，长约619米，宽约51米，与华盛顿纪念碑成直线排列，可清晰倒映纪念碑景观，是美国知名景点。为庆祝美国独立250周年，特朗普4月下令把倒影池底部涂层…"
