    "description": "当前正值岭南地区晚稻插秧关键期。7月31日，在广东省韶关市新丰县马头镇福水村，千亩连片的稻田里一片繁忙景象。据村干部介绍，福水村持续发力撂荒地整治与复耕复种，今年成功从江西引进种粮团队，落地近千亩连片水稻种植项目，日均带动近20名村民实现家门口就业，预计每年可为村民带来56万元稳定流转收益。 记者：李嘉乐 素材提供：韶关市新丰县融媒体中心 新华社音视频部制作",
