    "description": "新华社旧金山8月1日电（记者吴晓凌）美国西北部华盛顿州斯波坎县8月1日发生山火，迫使数千名居民撤离。华盛顿州州长鲍勃·弗格森当天宣布全州进入山火紧急状态。 华盛顿州自然资源部说，斯波坎县艾尔韦高地当天中午燃起山火，受强风、高温和植被干燥等因素影响，火势迅速蔓延。 截至当天晚间，山火过火面积达约2500英亩（约10平方公里）。当地官员说，部分建筑物遭到焚毁，但具体损失情况仍在评估中。 美国国家气象局当天对包括斯波坎县在内的华盛顿州东部发布…",
    "content": "新华社旧金山8月1日电（记者吴晓凌）美国西北部华盛顿州斯波坎县8月1日发生山火，迫使数千名居民撤离。华盛顿州州长鲍勃·弗格森当天宣布全州进入山火紧急状态。 华盛顿州自然资源部说，斯波坎县艾尔韦高地当天中午燃起山火，受强风、高温和植被干燥等因素影响，火势迅速蔓延。 截至当天晚间，山火过火面积达约2500英亩（约10平方公里）。当地官员说，部分建筑物遭到焚毁，但具体损失情况仍在评估中。 美国国家气象局当天对包括斯波坎县在内的华盛顿州东部发布了“特别危险状况”红旗警报。该气象局明确表示，在强风和干燥燃料共同作用的条件下，…"
