    "title": "美国爱达荷州快餐店枪击事件已致3死7伤",
    "link": "http://www.news.cn/20260802/aeb6967f59af412596956568e5e5d774/c.html",
    "pub_date": "2026-08-02 15:16:44",
    "author": "吴晓凌",
    "description": "新华社旧金山8月1日电（记者吴晓凌）美国爱达荷州南部城市特温福尔斯一家汉堡快餐店8月1日发生枪击事件，已造成3人死亡、7人受伤。犯罪嫌疑人已死亡。 该市政府官员约书亚·帕默说，部分伤者情况危重。警方在事发快餐店附近发现犯罪嫌疑人的尸体，目前尚不清楚是否计入已公布的死亡人数中。该市警察局局长马修·希克斯在新闻发布会上表示，仍在核实嫌疑人的身份并调查其作案动机。",
    "content": "新华社旧金山8月1日电（记者吴晓凌）美国爱达荷州南部城市特温福尔斯一家汉堡快餐店8月1日发生枪击事件，已造成3人死亡、7人受伤。犯罪嫌疑人已死亡。 该市政府官员约书亚·帕默说，部分伤者情况危重。警方在事发快餐店附近发现犯罪嫌疑人的尸体，目前尚不清楚是否计入已公布的死亡人数中。该市警察局局长马修·希克斯在新闻发布会上表示，仍在核实嫌疑人的身份并调查其作案动机。"
